Yes, the `WithHideFunc` does what I need.

Example:

```
package main

import (
	"fmt"
	"github.com/charmbracelet/huh"
)

func main() {
	var useSqlDb bool
	var dbType string

	huh.NewForm(
		huh.NewGroup(huh.NewConfirm().Title("Do you want to use SQL database?").Value(&useSqlDb)),
		huh.NewGroup(
			huh.NewSelect[string]().
				Title("Choose your db type").
				Options(
					huh.NewOption("PostgreSQL", "postgresql"),
					huh.NewOption("MySQL", "mysql"),
					huh.NewOption("Oracle", "oracle"),
				).
				Value(&dbType),
		).WithHideFunc(func() bool {
			return !useSqlDb
		}),
	).Run()

	if useSqlDb {
		fmt.Println("Using SQL database of type " + dbType)
	} else {
		fmt.Println("Not using sql database")
	}
}
```

You can may be use `WithHideFunc` to conditionally show some questions. Here is the rewriten [example](https://github.com/charmbracelet/huh/blob/0f20f61417bfee7a1ec6f0f2f93a423d884b20ad/examples/conditional/main.go) of #75 (with corrected "Carrot" option for "vegetables" 🙂).

```golang
package main

import (
	"fmt"

	"github.com/charmbracelet/huh"
)

func main() {

	var (
		category string
		choice   string
	)

	huh.NewForm(
		huh.NewGroup(
			huh.NewSelect[string]().
				Title("What are you in the mood for?").
				Value(&category).
				Options(
					huh.NewOption("Some fruit", "fruits"),
					huh.NewOption("A vegetable", "vegetables"),
					huh.NewOption("A drink", "drinks"),
				),
		),
		huh.NewGroup(
			huh.NewSelect[string]().
				Title("Okay, what kind of fruits are you in the mood for?").
				Value(&choice).
				Options(
					huh.NewOption("Tangerine", "tangerine"),
					huh.NewOption("Canteloupe", "canteloupe"),
					huh.NewOption("Pomelo", "pomelo"),
					huh.NewOption("Grapefruit", "grapefruit"),
				),
		).WithHideFunc(func() bool {
			return category != "fruits"
		}),
		huh.NewGroup(
			huh.NewSelect[string]().
				Title("Okay, what kind of vegetables are you in the mood for?").
				Value(&choice).
				Options(
					huh.NewOption("Carrot", "carrot"),
					huh.NewOption("Jicama", "jicama"),
					huh.NewOption("Kohlrabi", "kohlrabi"),
					huh.NewOption("Fennel", "fennel"),
					huh.NewOption("Ginger", "ginger"),
				),
		).WithHideFunc(func() bool {
			return category != "vegetables"
		}),
		huh.NewGroup(
			huh.NewSelect[string]().
				Title("Okay, what kind of drinks are you in the mood for?").
				Value(&choice).
				Options(
					huh.NewOption("Coffee", "coffee"),
					huh.NewOption("Tea", "tea"),
					huh.NewOption("Bubble Tea", "bubble-tea"),
					huh.NewOption("Agua Fresca", "agua-fresca"),
