I took the existing `Text` and `Input` types and made them generic with marshal/unmarshal functions. You can drop these in your own project somewhere rather than waiting for something like this in **huh**.

<details>
  <summary>InputAny[T any] (a generic version of Input)</summary>

  ### field_inputany.go
  ```go
  package shell
  
  import (
  	"fmt"
  	"strings"
  
  	"github.com/charmbracelet/bubbles/key"
  	"github.com/charmbracelet/bubbles/textinput"
  	tea "github.com/charmbracelet/bubbletea"
  	"github.com/charmbracelet/huh"
  	"github.com/charmbracelet/huh/accessibility"
  	"github.com/charmbracelet/lipgloss"
  )
  
  // InputAny[T] is a generic form input field.
  type InputAny[T any] struct {
  	value    *T
  	strValue *string
  	key      string
  
  	// customization
  	title       string
  	description string
  	inline      bool
  
  	// marshaling T<->string
  	marshal   func(T) string
  	unmarshal func(string) (T, error)
  
  	// error handling
  	validate func(T) error
  	err      error
  
  	// model
  	textinput textinput.Model
  
  	// state
  	focused bool
  
  	// options
  	width      int
  	height     int
  	accessible bool
  	theme      *huh.Theme
  	keymap     huh.InputKeyMap
  }
  
  // NewInputAny returns a new input field.
  func NewInputAny[T any](marshal func(T) string, unmarshal func(string) (T, error)) *InputAny[T] {
  	input := textinput.New()
  
  	i := &InputAny[T]{
  		value:     new(T),
  		strValue:  new(string),
  		textinput: input,
  		validate:  func(T) error { return nil },
  		marshal:   marshal,
  		unmarshal: unmarshal,
  	}
  
  	return i
  }
  
  // Value sets the value of the input field.
  func (i *InputAny[T]) Value(value *T) *InputAny[T] {
  	i.value = value
  	strValue := i.marshal(*value)
  	i.strValue = &strValue
  	i.textinput.SetValue(*i.strValue)
  	return i
  }
  
  // Key sets the key of the input field.
  func (i *InputAny[T]) Key(key string) *InputAny[T] {
  	i.key = key
  	return i
  }
  
  // Title sets the title of the input field.
  func (i *InputAny[T]) Title(title string) *InputAny[T] {
  	i.title = title
  	return i
  }
  
  // Description sets the description of the input field.
  func (i *InputAny[T]) Description(description string) *InputAny[T] {
